def is_woodall(n):
    if n <= 0:
        return False
    if n == 1:
        return True

    # Remove factors of 2
    while n % 2 == 0:
        n //= 2

    # Check if n is a power of 2
    if n == 1:
        return True

    # Check if n is a prime
    is_prime = True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            is_prime = False
            break

    return is_prime
