def is_woodall(n):
    if n <= 1:
        return False
    # A number is Woodall if n = 2^p - 1 and 2^p - 1 is prime
    # First, check if n is of the form 2^p - 1
    p = 0
    temp = n + 1
    while temp % 2 == 0:
        temp //= 2
        p += 1
        if temp != 1:
            break

    if temp != 1:
        return False

    # Now check if 2^p - 1 is prime
    # Since we know n = 2^p - 1, we just need to check primality of n
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Check odd divisors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True
```

