def is_majority(arr, n, x):
	def binary_search(arr, low, high, x):
		if high >= low:
			mid = (low + high) // 2
			if arr[mid] == x:
				return mid
			elif x < arr[mid]:
				return binary_search(arr, low, mid - 1, x)
			else:
				return binary_search(arr, mid + 1, high, x)
		return -1

	if binary_search(arr, 0, n - 1, x) == -1:
		return False

	# If x exists, check if it is at the middle index
	if arr[n // 2] == x:
		return True
	return False
